#!/usr/bin/env node
'use strict';
/*
 * hg_check.js - zero-dependency self-test for an ESP32 running WLED + the "home_gadgets" usermod.
 *
 * AI: this file was generated by an AI (Claude). Review it before relying on it.
 *
 * Needs Node.js 18 or newer (uses the built-in fetch). No npm packages.
 *
 *   node hg_check.js --host <ip-or-name> [--key KEY] [--pin PIN] [--allow-switching --relay N] [--json]
 *
 * SAFETY
 *  - A default run sends only read-only requests, plus a few requests that a correct firmware rejects
 *    with HTTP 403 before doing anything (GET /home/api?relay=1&on=t without a key and with a wrong key,
 *    POST /home/cfg with the harmless body {} and no key). Relay 1 is read from /home/live before and
 *    after those requests; a change is reported as a loud FAIL. --passive skips these requests too.
 *  - A mains relay is switched ONLY with --allow-switching AND --relay N (and --key). The relay is put
 *    back into its original state afterwards and the restore is verified.
 *
 * Where the facts come from (read on 2026-09-29):
 *  - routes, key handling, field names: hg_team/releases/RC3b/src/home_gadgets.cpp (md5 f8f0ae43, the RC3b flash image)
 *    (routes :1897-1941, /home/cfg :969-1114, /home/live :1959-2019, /home/stats :2022-2036, /home/api :2045-2085,
 *     file names :93-104, key in NVS and migration :1177-1208 and :2134-2156)
 *  - /home page ETag: generated by RC3b/src/gen_page.py; the value below was read from the RC3b firmware image
 *  - pin map: TEAM_BOARD.md section 4 (unchanged in RC3b, home_gadgets.cpp:111-113)
 *  - WLED file server and file editor rules: wled00/file.cpp:478-497, wled00/wled_server.cpp:206-330
 *  - /json/pins format and owner ids: wled00/json.cpp:1110-1237, wled00/pin_manager.h:34-80
 *
 * Exit code: 0 = no FAIL, 1 = at least one FAIL (or device unreachable), 2 = bad command line.
 */

// ------------------------------------------------------------------ constants

const TOOL_VERSION = '1.1.2';     // 1.1.0: checks for release RC3b; 1.1.1: reports the "rel" release tag (RC4+); 1.1.2: accepts the RC4b page
const DEFAULT_TIMEOUT_MS = 5000;
const GAP_MS = 60;               // pause between requests, the ESP32 web server handles few connections at once
const SETTLE_MS = 1000;          // time for queued commands to run in the usermod's loop()
const HOLD_MS = 2000;            // how long a test relay stays switched
const COUNTDOWN_S = 3;           // time to press Ctrl+C before a relay is switched
const MIN_HEAP = 30 * 1024;      // WARN below this free heap
const WEAK_RSSI = -80;           // WARN at or below this WiFi RSSI (dBm); threshold chosen by this script

// RC3b home_gadgets.cpp:43-61 (built-in moods: 23 entries in HG_BUILTIN_MOODS, :274-298; 18 before contract v2)
const HG_RELAYS = 8, HG_SWITCHES = 8, HG_SENSORS = 2, HG_SCENES = 6, HG_CUSTOM_MOODS = 12, HG_BUILTIN_MOODS = 23;
const KEY_CHARS = 'abcdefghjkmnpqrstuvwxyz23456789';   // HG_KEY_CHARS
const KEY_RE = new RegExp('^[' + KEY_CHARS + ']{10}$');  // HG_KEY_LEN = 10
const HG_PX_SAMPLES = 16;        // colour samples per strip in /home/live "px" (:61)
const HG_STAT_SLOTS = 48;        // half-hour motion counters per PIR in /home/stats (:151)
const HG_SRC_MAX = 11;           // highest HgSource code in /home/live "src" (SRC_ALLOFF, :145-148)

// ETag of the /home page (gen_page.py: sha1 of the gzipped page). Read from the firmware images in hg_team/releases;
// RC3 and RC3b embed the same page (home.htm 837a38cf), so the page cannot tell those two apart
const PAGE_ETAGS = {
  '"hg-9c054055c6e7"': 'RC3 / RC3b page (home.htm 837a38cf)',
  '"hg-736a2c90fd05"': 'RC2 page',
  '"hg-c962f3f563cc"': 'RC4b page (home.htm 54348e10)',
};
const PAGE_ETAG_RC3B = '"hg-9c054055c6e7"';
// reviewed release pages that pass fw.page: RC3b and RC4b (RC4b = the current flash image, 84 PASS about 18:26)
const PAGE_ETAGS_OK = new Set([PAGE_ETAG_RC3B, '"hg-c962f3f563cc"']);

// pin owner ids (wled00/pin_manager.h, wled00/const.h)
const OWNER_HG = 59;             // PinOwner::UM_HomeGadgets = USERMOD_ID_HOME_GADGETS
const OWNER_AR = 32;             // PinOwner::UM_Audioreactive = USERMOD_ID_AUDIOREACTIVE
const OWNER_LED = 0x82;          // PinOwner::BusDigital ("LED Digital")
const OWNER_BUTTON = 0x85;       // PinOwner::Button

// expected pin map, TEAM_BOARD.md section 4 (same as HG_DEFAULT_*_PINS in RC3b home_gadgets.cpp:111-113)
const RELAY_PINS = [4, 13, 18, 19, 23, 25, 26, 27];
const SWITCH_PINS = [14, 32, 33, 21, 22, 5, 15, 35];
const PIR_PINS = [34, 39];
const MIC_PIN = 36;
const LED_PINS = [16, 17];
const BUTTON_PIN = 0;

// ------------------------------------------------------------------ command line

function usage() {
  return [
    'hg_check.js ' + TOOL_VERSION + ' - self-test for WLED + home_gadgets',
    '',
    'Usage: node hg_check.js --host <ip-or-name> [options]',
    '',
    '  --host H            device address, e.g. 192.168.1.50, wled-abcdef.local, http://192.168.1.50:80',
    '  --key KEY           the security key shown on /home (Settings > Voice control). Checked against the',
    '                      device and searched for in files that other web sites can read',
    '  --pin PIN           WLED settings PIN (only used to show that a PIN without the key is refused)',
    '  --allow-switching   allow the relay test; needs --relay N and --key. SWITCHES A MAINS RELAY',
    '  --relay N           relay number 1-8 for the switching test',
    '  --passive           read-only requests only (skips the requests that the device must refuse)',
    '  --json              print the results as JSON instead of a table',
    '  --timeout MS        per-request timeout, default ' + DEFAULT_TIMEOUT_MS,
    '  --no-color          no ANSI colours',
    '  -h, --help          this text',
    '',
    'Exit code: 0 = no FAIL, 1 = FAIL or device unreachable, 2 = bad command line.',
  ].join('\n');
}

function parseArgs(argv) {
  const o = { host: null, key: null, pin: null, allowSwitching: false, relay: null, json: false, passive: false,
    timeout: DEFAULT_TIMEOUT_MS, color: true, help: false };
  const needValue = (i, name) => {
    if (i + 1 >= argv.length || argv[i + 1].startsWith('--')) throw new Error(name + ' needs a value');
    return argv[i + 1];
  };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    switch (a) {
      case '--host': o.host = needValue(i, a); i++; break;
      case '--key': o.key = needValue(i, a).trim(); i++; break;
      case '--pin': o.pin = needValue(i, a).trim(); i++; break;
      case '--allow-switching': o.allowSwitching = true; break;
      case '--relay': o.relay = needValue(i, a); i++; break;
      case '--json': o.json = true; break;
      case '--passive': o.passive = true; break;
      case '--timeout': o.timeout = Number(needValue(i, a)); i++; break;
      case '--no-color': o.color = false; break;
      case '-h': case '--help': o.help = true; break;
      default: throw new Error('unknown option ' + a);
    }
  }
  if (o.help) return o;
  if (!o.host) throw new Error('--host is required');
  if (!Number.isFinite(o.timeout) || o.timeout < 500 || o.timeout > 60000) throw new Error('--timeout must be 500-60000 ms');
  if (o.relay !== null) {
    if (!/^[1-8]$/.test(o.relay)) throw new Error('--relay must be a number from 1 to 8');
    o.relay = Number(o.relay);
  }
  if (o.allowSwitching) {
    if (o.relay === null) throw new Error('--allow-switching needs an explicit --relay N (1-8)');
    if (!o.key) throw new Error('--allow-switching needs --key KEY (the relay is switched through the Siri API)');
    if (o.passive) throw new Error('--allow-switching and --passive cannot be combined');
  }
  if (o.key !== null && o.key === '') throw new Error('--key is empty');
  return o;
}

// ------------------------------------------------------------------ helpers

let OPT = null;
let BASE = '';
let netFailsInRow = 0;
let deviceGone = false;
const results = [];
let pendingRestore = null;   // {n, i, orig, key} while a test relay is not in its original state
let restoring = false;

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const enc = encodeURIComponent;
const onoff = (v) => (v ? 'ON' : 'OFF');
const mask = (k) => (k ? k.slice(0, 2) + '*'.repeat(Math.max(0, k.length - 2)) : '(none)');

function add(status, check, detail) {
  results.push({ status, check, detail: String(detail) });
}

// progress / safety notices: to stderr in --json mode so stdout stays valid JSON
function notice(msg) {
  if (OPT && OPT.json) process.stderr.write(msg + '\n');
  else process.stdout.write(msg + '\n');
}

function tryJson(text) {
  try { return JSON.parse(text); } catch (e) { return undefined; }
}

function baseUrl(host) {
  let h = host.trim();
  if (!/^https?:\/\//i.test(h)) h = 'http://' + h;
  return h.replace(/\/+$/, '');
}

// one HTTP request with timeout; never throws. Returns {ok, status, headers, text, ms} or {ok:false, error}
async function http(method, path, opts = {}) {
  if (deviceGone) return { ok: false, error: 'not sent: the device stopped responding', skipped: true };
  await sleep(GAP_MS);
  const attempts = method === 'GET' ? 2 : 1;   // retry a GET once after a dropped connection (not after a timeout)
  let last = null;
  for (let a = 0; a < attempts; a++) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), OPT.timeout);
    const t0 = Date.now();
    try {
      const res = await fetch(BASE + path, { method, headers: opts.headers, body: opts.body, signal: ctrl.signal, redirect: 'manual' });
      const text = await res.text();
      netFailsInRow = 0;
      return { ok: true, status: res.status, headers: res.headers, text, ms: Date.now() - t0 };
    } catch (e) {
      const aborted = e && e.name === 'AbortError';
      const cause = e && e.cause;
      const code = aborted ? 'TIMEOUT' : ((cause && cause.code) || 'ERROR');
      const detail = (cause && cause.message) || (e && e.message) || String(e);
      const msg = aborted ? 'no answer within ' + OPT.timeout + ' ms'
        : (code !== 'ERROR' ? code + ' (' + detail + ')' : detail === 'bad port' ? 'port refused by Node fetch (blocked port list)' : detail);
      last = { ok: false, error: msg, code };
      if (aborted || code === 'ECONNREFUSED' || code === 'ENOTFOUND' || code === 'EHOSTUNREACH' || code === 'ENETUNREACH') break;
      await sleep(300);
    } finally {
      clearTimeout(timer);
    }
  }
  if (++netFailsInRow >= 3) deviceGone = true;
  return last;
}

const getJson = async (path) => {
  const r = await http('GET', path);
  return Object.assign(r, { json: r.ok ? tryJson(r.text) : undefined });
};

const postJson = (path, obj) => http('POST', path, { body: JSON.stringify(obj), headers: { 'Content-Type': 'application/json' } });

// relay state from /home/live (0-based index), null if unknown
async function relayState(i) {
  const r = await getJson('/home/live');
  return r.json && Array.isArray(r.json.r) && i < r.json.r.length ? !!r.json.r[i] : null;
}

async function liveRev() {
  const r = await getJson('/home/live');
  return r.json && typeof r.json.rev === 'number' ? r.json.rev : null;
}

// polls /home/live until relay i has the wanted state or the time is up; returns the last state seen
async function waitRelay(i, want, ms) {
  const end = Date.now() + ms;
  let s = null;
  do {
    s = await relayState(i);
    if (s === want) return s;
    await sleep(250);
  } while (Date.now() < end);
  return s;
}

function httpDesc(r) {
  return r.ok ? 'HTTP ' + r.status : 'request failed: ' + r.error;
}

// ------------------------------------------------------------------ checks: device info

async function checkInfo() {
  const r = await getJson('/json/info');
  if (!r.ok) {
    add('FAIL', 'reach', 'cannot reach ' + BASE + ': ' + r.error + '. Check that the device is powered, that this PC is ' +
      'on the same network, and the address (router list or WLED app). In access point mode join WLED-AP and use 4.3.2.1.');
    return null;
  }
  if (r.status !== 200 || !r.json || typeof r.json !== 'object') {
    add('FAIL', 'reach', 'GET /json/info gave ' + httpDesc(r) + ' without WLED JSON - is this a WLED device?');
    return null;
  }
  const j = r.json;
  add('PASS', 'reach', 'WLED ' + j.ver + ' (build ' + j.vid + '), release "' + j.release + '", arch ' + j.arch +
    ', name "' + j.name + '", ip ' + (j.ip || '?') + ' (' + r.ms + ' ms)');
  // /json/info has no home_gadgets version: "vid" is WLED's fixed VERSION (wled00/wled.h), the same for every RC
  add('INFO', 'fw.build', 'ver ' + j.ver + ', vid ' + j.vid + ', codename ' + j.cn + ', release "' + j.release + '", repo ' + j.repo +
    ', core ' + j.core + '. /json/info carries no release-candidate tag; see fw.page and fw.rc3b');

  if (typeof j.arch === 'string' && !/esp32/i.test(j.arch)) add('FAIL', 'info.arch', 'arch "' + j.arch + '": home_gadgets needs a classic ESP32');
  if (typeof j.release === 'string') {
    if (/V4/i.test(j.release)) add('PASS', 'info.build', 'release "' + j.release + '" is an ESP-IDF V4 build (needed for the analog MAX4466 mic)');
    else add('WARN', 'info.build', 'release "' + j.release + '" does not look like the V4 build; the analog mic only works in V4 ' +
      '(env home_gadgets extends esp32dev_V4)');
  }

  if (typeof j.freeheap === 'number') {
    const kb = (j.freeheap / 1024).toFixed(1);
    if (j.freeheap < MIN_HEAP) add('WARN', 'info.heap', 'free heap ' + kb + ' KB (< 30 KB); ESP32 tends to crash when the largest free block gets small');
    else add('PASS', 'info.heap', 'free heap ' + kb + ' KB');
  } else add('WARN', 'info.heap', 'no freeheap field in /json/info');

  if (typeof j.uptime === 'number') {
    const s = j.uptime, h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60);
    add('INFO', 'info.uptime', 'uptime ' + (h ? h + ' h ' : '') + m + ' min ' + (s % 60) + ' s' +
      (s < 10 ? ' - just booted: a new security key is created about 5 s after boot, once WiFi or the access point runs' : ''));
  }

  const w = j.wifi || {};
  if (typeof w.rssi === 'number') {
    const d = 'RSSI ' + w.rssi + ' dBm, signal ' + w.signal + '%, channel ' + w.channel + (w.ap ? ', access point active' : '');
    if (w.rssi <= WEAK_RSSI) add('WARN', 'info.wifi', d + ' - weak (this script warns at ' + WEAK_RSSI + ' dBm); Siri links may time out');
    else add('PASS', 'info.wifi', d);
  } else add('INFO', 'info.wifi', 'no WiFi details in /json/info');

  const u = j.u && j.u['Home Gadgets'];
  if (!Array.isArray(u)) add('FAIL', 'usermod', 'no "Home Gadgets" entry in /json/info: this firmware does not contain the home_gadgets usermod (wrong build flashed?)');
  else if (u.some((x) => String(x).includes('disabled'))) add('FAIL', 'usermod', 'home_gadgets is DISABLED: Settings > Usermods > HomeGadgets > enabled');
  else add('PASS', 'usermod', 'home_gadgets active, ' + u[0] + ' relay(s) on');
  return j;
}

// ------------------------------------------------------------------ checks: /home page and config

async function checkHomePage() {
  const r = await http('GET', '/home');
  if (!r.ok) { add('FAIL', 'home.page', 'GET /home: ' + r.error); return; }
  if (r.status !== 200) { add('FAIL', 'home.page', 'GET /home gave HTTP ' + r.status + ' (expected 200)'); return; }
  const ce = r.headers.get('content-encoding');
  const html = /<html|<!doctype/i.test(r.text);
  add(html ? 'PASS' : 'WARN', 'home.page', 'HTTP 200, ' + r.text.length + ' bytes after decoding' +
    (ce ? ', Content-Encoding: ' + ce : ', not compressed') + (r.headers.get('etag') ? ', ETag set' : '') + (html ? '' : ', but the body does not look like HTML'));

  // which page build is embedded (the only build marker the device exposes)
  const etag = r.headers.get('etag');
  if (!etag) add('WARN', 'fw.page', 'GET /home has no ETag: not an RC build of home_gadgets');
  else if (PAGE_ETAGS_OK.has(etag)) add('PASS', 'fw.page', 'ETag ' + etag + ' = ' + PAGE_ETAGS[etag] + '. RC3 and RC3b embed the same page, so this alone cannot tell them apart');
  else add('WARN', 'fw.page', 'ETag ' + etag + ' = ' + (PAGE_ETAGS[etag] || 'an unknown page build') + ', not the RC3b page (' + PAGE_ETAG_RC3B +
    '): RC3b is not running, or a later release is (then update PAGE_ETAG_RC3B in hg_check.js)');
}

// X17: unknown /home/... paths must get 404, not the /home page (RC3b home_gadgets.cpp:1924-1929)
async function checkUnknownRoute() {
  const r = await http('GET', '/home/xyz-unknown');
  if (!r.ok) { add(r.skipped ? 'SKIP' : 'WARN', 'home.unknown', 'GET /home/xyz-unknown: ' + r.error); return; }
  if (r.status === 404) add('PASS', 'home.unknown', 'GET /home/xyz-unknown gives HTTP 404 (X17)');
  else if (r.status === 200 && /<html|<!doctype/i.test(r.text)) add('FAIL', 'home.unknown', 'GET /home/xyz-unknown gives HTTP 200 with the /home page: ' +
    'the X17 fix is missing, so this firmware is older than RC3b');
  else add('WARN', 'home.unknown', 'GET /home/xyz-unknown gives unexpected HTTP ' + r.status + ' (expected 404)');
}

// GET /home/cfg: header, shape, pin errors, pin map. Returns the parsed config or null.
async function checkConfig() {
  const r = await getJson('/home/cfg');
  if (!r.ok) { add('FAIL', 'cfg', 'GET /home/cfg: ' + r.error); return null; }
  if (r.status !== 200 || !r.json || typeof r.json !== 'object' || Array.isArray(r.json)) {
    add('FAIL', 'cfg', 'GET /home/cfg gave ' + httpDesc(r) + ' without a JSON object - home_gadgets routes missing (old or wrong firmware)');
    return null;
  }
  const c = r.json;

  // security: the key is only allowed in a response that other web sites cannot read
  const acao = r.headers.get('access-control-allow-origin');
  if (acao !== null) add('FAIL', 'sec.cfg-cors', 'GET /home/cfg carries Access-Control-Allow-Origin: ' + acao + ' - any web page could read the key');
  else add('PASS', 'sec.cfg-cors', 'GET /home/cfg has no Access-Control-Allow-Origin header (other web sites cannot read the key)');
  const cc = r.headers.get('cache-control') || '';
  if (!/no-store/i.test(cc)) add('WARN', 'sec.cfg-cache', 'GET /home/cfg without Cache-Control: no-store (got "' + cc + '")');

  // X15: pinSet (contract v2.1, a JSON boolean; RC3b home_gadgets.cpp:1097). Without a settings PIN, WLED's /upload
  // accepts any file from any web page (wled00/wled_server.cpp:206-210)
  if (typeof c.pinSet !== 'boolean') add('FAIL', 'sec.pin-set', 'pinSet in /home/cfg is ' + ('pinSet' in c ? JSON.stringify(c.pinSet) + ', not a JSON boolean' : 'missing') +
    ' (contract v2.1): the page cannot show its "No settings PIN" warning; firmware older than RC3b');
  else if (c.pinSet === false) add('WARN', 'sec.pin-set', 'No WLED settings PIN — any web page on your network can upload files to this device; ' +
    'set one in Settings → Security & Updates');
  else add('PASS', 'sec.pin-set', 'a WLED settings PIN is set (pinSet=true): /upload, /edit and the settings pages need it');

  // shape
  const problems = [];
  const len = (a) => (Array.isArray(a) ? a.length : -1);
  if (c.v !== 1) problems.push('v=' + c.v + ' (expected 1)');
  if (len(c.relays) !== HG_RELAYS) problems.push('relays: ' + len(c.relays) + ' (expected 8)');
  if (len(c.sw) !== HG_SWITCHES) problems.push('sw: ' + len(c.sw) + ' (expected 8)');
  if (len(c.pir) !== HG_SENSORS) problems.push('pir: ' + len(c.pir) + ' (expected 2)');
  if (len(c.sc) !== HG_SCENES) problems.push('sc: ' + len(c.sc) + ' (expected 6)');
  if (len(c.bm) !== HG_BUILTIN_MOODS) problems.push('bm (built-in moods): ' + len(c.bm) + ' (expected ' + HG_BUILTIN_MOODS + ')');
  if (len(c.moods) < 0 || len(c.moods) > HG_CUSTOM_MOODS) problems.push('moods (custom): ' + len(c.moods) + ' (expected 0-12)');
  if (!c.lim || typeof c.lim !== 'object') problems.push('lim missing');
  if (!Array.isArray(c.seg) || c.seg.length !== 2) problems.push('seg: expected 2 segment ids');
  if (problems.length) add('FAIL', 'cfg.shape', problems.join('; '));
  else add('PASS', 'cfg.shape', '8 relays, 8 switches, 2 PIRs, 6 scenes, ' + HG_BUILTIN_MOODS + ' built-in moods, ' + c.moods.length +
    ' custom mood(s); LED 1 = segment ' + c.seg[0] + ', LED 2 = segment ' + c.seg[1]);
  if (problems.length) return c;

  // pin allocation errors reported by the usermod: e=1 not a usable pin, e=2 pin used by something else
  const errs = [];
  const collect = (arr, label) => arr.forEach((o, i) => {
    if (o && o.e) errs.push(label + ' ' + (i + 1) + ' (GPIO ' + o.p + '): ' + (o.e === 2 ? 'pin already used by ' + (o.o || 'another function') : 'not a usable pin for this'));
  });
  collect(c.relays, 'Relay'); collect(c.sw, 'Switch'); collect(c.pir, 'PIR');
  if (errs.length) add('FAIL', 'cfg.pin-errors', errs.join('; '));
  else add('PASS', 'cfg.pin-errors', 'no pin allocation errors (no e=1/e=2 in /home/cfg)');

  // configured pins against the board map
  const diff = [];
  const cmp = (arr, pins, label) => arr.forEach((o, i) => { if (o.p !== pins[i]) diff.push(label + ' ' + (i + 1) + ' on GPIO ' + o.p + ' (map: ' + pins[i] + ')'); });
  cmp(c.relays, RELAY_PINS, 'Relay'); cmp(c.sw, SWITCH_PINS, 'Switch'); cmp(c.pir, PIR_PINS, 'PIR');
  if (diff.length) add('WARN', 'cfg.pin-map', 'configured pins differ from TEAM_BOARD section 4 (changed on the Wiring tab?): ' + diff.join('; '));
  else add('PASS', 'cfg.pin-map', 'configured pins match TEAM_BOARD section 4');

  // switch -> relay mapping and relay options (information for the per-channel tests)
  const map = c.sw.map((s, i) => (i + 1) + '->' + (s.r >= 0 ? 'R' + (s.r + 1) : 'none') + (s.t === 1 ? '' : '(dry)') + (s.m === 1 ? '(follow)' : '') + (s.inv ? '(inv)' : ''));
  add('INFO', 'cfg.switches', 'wall switch -> relay: ' + map.join(' ') + ' (default: AC module, toggle mode, signal LOW = on)');
  const po = ['off', 'on', 'last'];
  const rel = c.relays.map((x, i) => (i + 1) + ':' + (x.al ? 'LOW' : 'HIGH') + '/' + (po[x.po] || x.po) + (x.keep ? '/keep' : '') + (x.ao ? '/ao' + x.ao + 'm' : ''));
  add('INFO', 'cfg.relays', 'relay active level / power-on state / options: ' + rel.join(' '));
  const pir = c.pir.map((p, i) => (i + 1) + ':' + (p.en ? 'on' : 'OFF') + (p.night ? '/night-only' : '') + '/hold ' + p.hold + 's/' + (Array.isArray(p.a) ? p.a.length : 0) + ' action(s)');
  add('INFO', 'cfg.pir', 'PIR sensors: ' + pir.join(' '));
  if (c.ce) add('WARN', 'cfg.error', 'ce=true: the last configuration upload could not be applied');
  add('INFO', 'cfg.pin', c.pinReq ? 'a WLED settings PIN is set and currently locked (pinReq=true)'
    : c.pinSet === true ? 'a WLED settings PIN is set and unlocked right now (pinReq=false; 15 min after it was entered in WLED\'s settings)'
      : 'no WLED settings PIN is set, or it is unlocked right now (pinReq=false)');
  return c;
}

function checkKey(c, userKey) {
  let devKey = null;
  if (!c || !('key' in c)) {
    if (c) add('FAIL', 'sec.key', 'no "key" field in /home/cfg: firmware older than the security-key build (X7)');
    else add('SKIP', 'sec.key', '/home/cfg not available');
  } else if (c.key === '') {
    add('WARN', 'sec.key', 'the device has no key yet: it is created about 5 s after boot, once WiFi or the access point runs. Run the check again in a few seconds');
  } else if (typeof c.key !== 'string' || !KEY_RE.test(c.key)) {
    add('FAIL', 'sec.key', 'unexpected key format (' + mask(String(c.key)) + '): expected 10 characters from "' + KEY_CHARS + '"');
  } else {
    devKey = c.key;
    add('PASS', 'sec.key', 'key present (' + mask(devKey) + '), 10 characters from the allowed set');
  }
  if (userKey) {
    if (!devKey) add('SKIP', 'sec.key-match', 'cannot compare --key: the device key is not available');
    else if (devKey === userKey) add('PASS', 'sec.key-match', '--key matches the device key');
    else add('FAIL', 'sec.key-match', '--key (' + mask(userKey) + ') differs from the device key (' + mask(devKey) + '): Siri links with the ' +
      'old key get HTTP 403. Was "Make a new key" pressed, or the file system reset? Copy the links again from /home');
  }
  return devKey;
}

async function checkLive() {
  const r = await getJson('/home/live');
  if (!r.ok || r.status !== 200 || !r.json) { add('FAIL', 'live', 'GET /home/live gave ' + httpDesc(r) + (r.ok && !r.json ? ' without JSON' : '')); return null; }
  const L = r.json;

  // X13: live status shows when someone is at home, so other web sites must not read it (RC3b home_gadgets.cpp:1960)
  const acao = r.headers.get('access-control-allow-origin');
  if (acao !== null) add('FAIL', 'sec.live-cors', 'GET /home/live carries Access-Control-Allow-Origin: ' + acao + ' - any web page can read relay and motion state (X13)');
  else add('PASS', 'sec.live-cors', 'GET /home/live has no Access-Control-Allow-Origin header (X13)');

  // contract v2 / v2.1 fields (RC3b home_gadgets.cpp:1988-2018): src[8] 0-11, ago[8], away, clap, ts, px[2]
  const nf = [];
  const isInt = (x) => Number.isInteger(x);
  const flag = (x) => x === 0 || x === 1;
  if (!Array.isArray(L.src) || L.src.length !== HG_RELAYS || !L.src.every((x) => isInt(x) && x >= 0 && x <= HG_SRC_MAX)) nf.push('src should be 8 codes 0-' + HG_SRC_MAX);
  if (!Array.isArray(L.ago) || L.ago.length !== HG_RELAYS || !L.ago.every((x) => isInt(x) && x >= 0)) nf.push('ago should be 8 numbers of seconds');
  for (const k of ['away', 'clap', 'ts']) if (!flag(L[k])) nf.push(k + ' should be 0 or 1 (got ' + JSON.stringify(L[k]) + ')');
  const pxOk = (p) => p === null || (Array.isArray(p) && p.length === HG_PX_SAMPLES && p.every((x) => typeof x === 'string' && /^[0-9a-f]{6}$/i.test(x)));
  if (!Array.isArray(L.px) || L.px.length !== 2 || !L.px.every(pxOk)) nf.push('px should be 2 entries, each null or ' + HG_PX_SAMPLES + ' six-digit hex colours');
  if (nf.length) add('FAIL', 'live.fields', nf.join('; ') + ' - firmware older than RC3b, or it does not match the page');
  else add('PASS', 'live.fields', 'src ' + L.src.join(',') + ', away ' + L.away + ', clap armed ' + L.clap + ', px ' +
    L.px.map((p) => (p ? p.length + ' colours' : 'null')).join(' / ') + ', ' +
    (L.ts ? 'time synced' : 'time NOT synced (schedules and away mode wait for NTP)'));

  const problems = [];
  const arr = (k, n) => { if (!Array.isArray(L[k]) || L[k].length !== n) problems.push(k + ' should have ' + n + ' entries'); };
  arr('r', HG_RELAYS); arr('sw', HG_SWITCHES); arr('pir', HG_SENSORS); arr('act', HG_SENSORS); arr('s', 2);
  for (const k of ['on', 'bri', 'mic', 'lvl', 'vol', 'rev']) if (typeof L[k] !== 'number') problems.push(k + ' missing');
  if (problems.length) { add('FAIL', 'live.shape', problems.join('; ')); return L; }
  const bits = (a) => a.map((x) => (x ? '1' : '0')).join('');
  add('PASS', 'live.shape', 'relays ' + bits(L.r) + ', wall switches ' + bits(L.sw) + ', PIR ' + bits(L.pir) + ' (1 = on, relay/switch 1 first)');
  L.s.forEach((s, k) => {
    if (s === null) add('WARN', 'live.led' + (k + 1), 'LED ' + (k + 1) + ': its WLED segment does not exist. LED Preferences: two outputs (GPIO 16 and 17) ' +
      'and tick "Make a segment for each output"');
    else add('PASS', 'live.led' + (k + 1), 'LED ' + (k + 1) + ': ' + (s.on ? 'on' : 'off') + ', segment brightness ' + s.bri + ', effect "' + s.fx + '"');
  });
  if (L.vol === -1) add('WARN', 'live.mic', 'no sound level (vol=-1): AudioReactive is not enabled. Settings > Usermods > AudioReactive, analog mic on GPIO 36');
  else add('PASS', 'live.mic', 'sound level ' + L.vol + '/255, microphone ' + (L.mic ? 'on' : 'OFF (switched off on /home)') + ', input level ' + L.lvl);
  const known = new Set(['r', 'sw', 'pir', 'act', 's', 'on', 'bri', 'mic', 'lvl', 'vol', 'rev', 'src', 'ago', 'away', 'clap', 'ts', 'px']);
  const extra = Object.keys(L).filter((k) => !known.has(k));
  if (extra.length) add('INFO', 'live.extra', 'extra /home/live fields (newer firmware): ' + extra.join(', '));
  return L;
}

let statsSeen = false;   // /home/stats answered with JSON (used by the open.read information)

// X13 + contract v2: GET /home/stats = {ts, on:[8], pir:[[48],[48]]}, no ACAO (RC3b home_gadgets.cpp:2022-2036)
async function checkStats() {
  const r = await http('GET', '/home/stats');
  if (!r.ok) { add(r.skipped ? 'SKIP' : 'FAIL', 'stats.shape', 'GET /home/stats: ' + r.error); return; }
  const j = r.status === 200 ? tryJson(r.text) : undefined;
  if (j === undefined) {
    add('FAIL', 'stats.shape', 'GET /home/stats gave HTTP ' + r.status + ' without JSON' +
      (r.status === 200 ? ' (the /home page answers unknown /home/... paths)' : '') + ': firmware older than RC3b');
    return;
  }
  statsSeen = true;
  const acao = r.headers.get('access-control-allow-origin');
  if (acao !== null) add('FAIL', 'sec.stats-cors', 'GET /home/stats carries Access-Control-Allow-Origin: ' + acao + ' - any web page can read when people are at home (X13)');
  else add('PASS', 'sec.stats-cors', 'GET /home/stats has no Access-Control-Allow-Origin header (X13)');
  const p = [];
  const nums = (a, n) => Array.isArray(a) && a.length === n && a.every((x) => Number.isInteger(x) && x >= 0);
  if (!j || typeof j !== 'object' || Array.isArray(j)) p.push('not a JSON object');
  else {
    if (j.ts !== 0 && j.ts !== 1) p.push('ts should be 0 or 1 (got ' + JSON.stringify(j.ts) + ')');
    if (!nums(j.on, HG_RELAYS)) p.push('on should be ' + HG_RELAYS + ' numbers of seconds');
    if (!Array.isArray(j.pir) || j.pir.length !== HG_SENSORS || !j.pir.every((a) => nums(a, HG_STAT_SLOTS))) p.push('pir should be ' + HG_SENSORS + ' x ' + HG_STAT_SLOTS + ' counts');
  }
  if (p.length) add('FAIL', 'stats.shape', 'GET /home/stats: ' + p.join('; '));
  else add('PASS', 'stats.shape', 'ts ' + j.ts + (j.ts ? ' (day follows the local clock)' : ' (no clock: 24 h periods of uptime)') + ', on-seconds today ' + j.on.join(',') +
    ', motion counts today ' + j.pir.map((a) => a.reduce((s, x) => s + x, 0)).join(' / '));
}

async function checkState() {
  const r = await getJson('/json/state');
  if (!r.ok || !r.json) { add('WARN', 'state', 'GET /json/state gave ' + httpDesc(r)); return; }
  const hg = r.json.HomeGadgets;
  if (!hg) add('WARN', 'state', 'no "HomeGadgets" object in /json/state (usermod disabled?)');
  else if (!Array.isArray(hg.r) || hg.r.length !== HG_RELAYS || !Array.isArray(hg.sw) || !Array.isArray(hg.pir)) add('FAIL', 'state', 'HomeGadgets object in /json/state has an unexpected shape');
  else add('PASS', 'state', '/json/state contains HomeGadgets {r[8], sw[8], pir[2]}');
}

async function checkEffects(c) {
  const e = await getJson('/json/eff');
  const f = await getJson('/json/fxdata');
  if (!Array.isArray(e.json) || !Array.isArray(f.json)) {
    add('FAIL', 'fx.lists', 'effect lists not readable: /json/eff ' + httpDesc(e) + ', /json/fxdata ' + httpDesc(f));
    return;
  }
  if (e.json.length === f.json.length) add('PASS', 'fx.lists', e.json.length + ' effects in /json/eff and /json/fxdata');
  else add('FAIL', 'fx.lists', '/json/eff has ' + e.json.length + ' entries but /json/fxdata has ' + f.json.length);
  if (c && Array.isArray(c.bm)) {
    const names = new Set(e.json.map((n) => String(n).toLowerCase()));
    const missing = c.bm.filter((m) => m && m.fx && !names.has(String(m.fx).toLowerCase())).map((m) => m.n + ' (' + m.fx + ')');
    if (missing.length) add('WARN', 'fx.moods', 'mood effects missing from this firmware, these moods fall back to effect 0 (Solid): ' + missing.join(', '));
    else add('PASS', 'fx.moods', 'the effects of all ' + c.bm.length + ' built-in moods exist');
  }
}

// /json/pins: owner of each pin against TEAM_BOARD section 4
async function checkPins(c) {
  const r = await getJson('/json/pins');
  if (!r.ok || !r.json || !Array.isArray(r.json.pins)) { add('FAIL', 'pins', 'GET /json/pins gave ' + httpDesc(r) + ' without a pins list'); return; }
  const pins = new Map(r.json.pins.map((p) => [p.p, p]));
  const cfgErr = new Map();
  if (c && Array.isArray(c.relays)) {
    [...c.relays, ...(c.sw || []), ...(c.pir || [])].forEach((o) => { if (o && o.e) cfgErr.set(o.p, o.e === 2 ? 'e=2 in /home/cfg' : 'e=1 in /home/cfg'); });
  }
  const ownerTxt = (p) => (p.n || 'unknown') + ' (id ' + p.o + ')';
  // missingLevel: status when the pin is free (FAIL for usermod pins, WARN where a setting is still missing)
  const group = (id, label, list, owner, ownerName, missingLevel, missingHint) => {
    const bad = []; let worst = 'PASS';
    list.forEach(([gpio, what]) => {
      const p = pins.get(gpio);
      const extra = cfgErr.has(gpio) ? ', ' + cfgErr.get(gpio) : '';
      if (!p) { bad.push(what + ' GPIO ' + gpio + ' not listed (not usable on this chip)'); worst = 'FAIL'; }
      else if (!p.a) { bad.push(what + ' GPIO ' + gpio + ' not allocated' + extra + (missingHint ? ' - ' + missingHint : '')); if (worst !== 'FAIL') worst = missingLevel; }
      else if (p.o !== owner) { bad.push(what + ' GPIO ' + gpio + ' owned by ' + ownerTxt(p) + ', expected ' + ownerName + extra); worst = 'FAIL'; }
    });
    if (bad.length) add(worst, id, bad.join('; '));
    else add('PASS', id, label + ': ' + list.map(([g]) => g).join(', ') + ' owned by ' + ownerName);
  };
  group('pins.relays', 'relay GPIOs', RELAY_PINS.map((g, i) => [g, 'Relay ' + (i + 1)]), OWNER_HG, 'home_gadgets (59)', 'FAIL');
  group('pins.switches', 'wall switch GPIOs', SWITCH_PINS.map((g, i) => [g, 'Switch ' + (i + 1)]), OWNER_HG, 'home_gadgets (59)', 'FAIL');
  group('pins.pir', 'PIR GPIOs', PIR_PINS.map((g, i) => [g, 'PIR ' + (i + 1)]), OWNER_HG, 'home_gadgets (59)', 'FAIL');
  group('pins.mic', 'microphone GPIO', [[MIC_PIN, 'Mic']], OWNER_AR, 'AudioReactive (32)', 'WARN',
    'enable AudioReactive (Settings > Usermods) with the analog mic on GPIO 36');
  group('pins.leds', 'LED data GPIOs', LED_PINS.map((g, i) => [g, 'LED ' + (i + 1)]), OWNER_LED, 'LED Digital (0x82)', 'WARN',
    'LED Preferences: two outputs, GPIO 16 and 17');
  group('pins.button', 'button GPIO', [[BUTTON_PIN, 'BOOT button']], OWNER_BUTTON, 'Button (0x85)', 'WARN',
    'button 0 is not configured on GPIO 0 (LED Preferences > Buttons); the 5-10 s access point / >10 s reset hold then does not work');

  const expected = new Set([...RELAY_PINS, ...SWITCH_PINS, ...PIR_PINS]);
  const stray = r.json.pins.filter((p) => p.a && p.o === OWNER_HG && !expected.has(p.p)).map((p) => p.p);
  if (stray.length) add('FAIL', 'pins.extra', 'home_gadgets owns GPIO ' + stray.join(', ') + ', which is not in the board map (pin changed on the Wiring tab?)');
  const p12 = pins.get(12);
  if (p12 && p12.a) add('WARN', 'pins.gpio12', 'GPIO 12 is used by ' + ownerTxt(p12) + ': the board does not boot if it is HIGH at power-on (review 5.2)');
}

// ------------------------------------------------------------------ checks: key leaks through files and the file editor

async function checkLeaks(keys) {
  const has = (text) => keys.some((k) => text.toLowerCase().includes(k.toLowerCase()));
  const scan = keys.length > 0;
  if (!scan) add('SKIP', 'sec.leak', 'no key known (neither --key nor /home/cfg), so file bodies cannot be searched for it');
  const reachable = [];

  // [path, id, what the file is]
  // RC3b: config /hgcfg_wsec.json (+ .tmp), relay states /hgstate_wsec.json, key in NVS (home_gadgets.cpp:93-108).
  // /home.json, /home.tmp, /hgstate.json and /hgwsec.json(.tmp) are files of earlier versions that RC3b migrates at boot
  const urls = [
    ['/home.json', 'sec.leak /home.json', 'X11'],
    ['/home.tmp', 'sec.leak /home.tmp', 'X11'],
    ['/hgwsec.json', 'sec.leak /hgwsec.json', 'X11b'],
    ['/hgwsec.json.tmp', 'sec.leak /hgwsec.json.tmp', 'X11b'],
    ['/hgcfg_wsec.json', 'sec.leak /hgcfg_wsec.json', 'X20'],
    ['/hgcfg_wsec.json.tmp', 'sec.leak /hgcfg_wsec.json.tmp', 'X20'],
    ['/hgstate_wsec.json', 'sec.leak /hgstate_wsec.json', 'X20'],
    ['/edit?func=edit&path=/hgwsec.json', 'sec.leak edit hgwsec', 'X11b'],
    ['/edit?func=download&path=/hgwsec.json', 'sec.leak dl hgwsec', 'X11b'],
    ['/edit?func=edit&path=/hgwsec.json.tmp', 'sec.leak edit hgwsec.tmp', 'X11b'],
    ['/edit?func=edit&path=/hgcfg_wsec.json', 'sec.leak edit hgcfg_wsec', 'X20'],
    ['/edit?func=download&path=/hgcfg_wsec.json', 'sec.leak dl hgcfg_wsec', 'X20'],
    ['/edit?func=edit&path=/hgcfg_wsec.json.tmp', 'sec.leak edit hgcfg_wsec.tmp', 'X20'],
    ['/edit?func=edit&path=/hgstate_wsec.json', 'sec.leak edit hgstate_wsec', 'X20'],
    ['/edit?func=edit&path=/home.json', 'sec.leak edit home.json', 'X11'],
    ['/edit?func=edit&path=/home.tmp', 'sec.leak edit home.tmp', 'X11'],
    ['/presets.json', 'sec.leak /presets.json', 'X12'],
    ['/ir.json', 'sec.leak /ir.json', 'X12'],
    ['/hgstate.json', 'sec.leak /hgstate.json', ''],
    ['/cfg.json', 'sec.leak /cfg.json', ''],
    ['/json', 'sec.leak /json', ''],
    ['/json/cfg', 'sec.leak /json/cfg', ''],
    ['/home/live', 'sec.leak /home/live', ''],
  ];
  const OLD_FILES = new Set(['/home.json', '/home.tmp', '/hgstate.json']);
  for (const [path, id, tag] of urls) {
    const r = await http('GET', path);
    if (!r.ok) { add(r.skipped ? 'SKIP' : 'WARN', id, 'could not check: ' + r.error); continue; }
    const tagTxt = tag ? ' [' + tag + ']' : '';
    if (scan && has(r.text)) {
      add('FAIL', id, 'THE KEY IS IN THE BODY (HTTP ' + r.status + ')' + tagTxt + ' - any web page can read it. Do not connect mains until fixed');
      continue;
    }
    const j = tryJson(r.text);
    const viaEdit = path.startsWith('/edit');
    const file = viaEdit ? path.slice(path.indexOf('path=') + 5) : path;   // the file system path
    const isKeyFile = path.includes('hgwsec');
    if (isKeyFile && r.status === 200) {
      // served at all is wrong, even if the key did not match
      add('FAIL', id, 'HTTP 200: the key file is served' + tagTxt + (j && j.k ? ' (it contains a "k" field)' : ''));
      continue;
    }
    if (viaEdit && isKeyFile) {
      // RC3b keeps the key in NVS and deletes the old key file at boot once the key is there (home_gadgets.cpp:2140-2150).
      // The file editor answers 404 for a missing file before it refuses "wsec.json" names with 403 (wled_server.cpp:299-307)
      if (r.status === 404) add('PASS', id, 'HTTP 404: ' + file + ' does not exist (RC3b keeps the key in NVS)');
      else if (r.status === 403) add('WARN', id, 'HTTP 403: refused, but ' + file + ' EXISTS. RC3b deletes it at boot once the key is in NVS, so ' +
        'either the move to NVS failed or the file was uploaded after the last boot. Reboot and check again; if it stays, tell the builder');
      else if (r.status === 401) add('PASS', id, 'HTTP 401: the file editor is locked by the settings PIN (whether the old key file exists cannot be checked)');
      else add('WARN', id, 'unexpected HTTP ' + r.status);
      continue;
    }
    if (/_wsec\.json/.test(file)) {
      // X20: configuration and relay state files must never be served, neither directly nor by the file editor
      if (r.status === 200) add('FAIL', id, 'HTTP 200: ' + file + ' is served' + tagTxt + ' - any web page can read it (away mode, schedules, relay names)');
      else if (!viaEdit && (r.status === 404 || r.status === 403)) add('PASS', id, 'HTTP ' + r.status + ': not served (the name contains "sec")');
      else if (viaEdit && r.status === 403) add('PASS', id, 'HTTP 403: the file editor refuses ' + file + ' (the file exists)');
      else if (viaEdit && r.status === 401) add('PASS', id, 'HTTP 401: the file editor is locked by the settings PIN');
      else if (viaEdit && r.status === 404) add('PASS', id, 'HTTP 404: ' + file + ' does not exist yet' +
        (file === '/hgcfg_wsec.json' ? ' (no settings saved yet: defaults in use)' : ' (normal)'));
      else add('WARN', id, 'unexpected HTTP ' + r.status);
      continue;
    }
    if (path === '/home.json' && r.status === 200 && j && typeof j === 'object' && j.key) {
      add('FAIL', id, 'HTTP 200 and /home.json still has a "key" field (legacy key not migrated)' + tagTxt);
      continue;
    }
    if (OLD_FILES.has(file) && r.status === 200) {
      // RC3b renames these at boot (migrateFiles, home_gadgets.cpp:632-647); still present = the migration did not complete
      if (!viaEdit) reachable.push(path);
      add('WARN', id, 'HTTP 200' + (scan ? ', key not in the body' : ' (body not searched)') + ', but ' + file +
        ' (a file of an earlier version) STILL EXISTS: the migration did not complete. ' +
        'Any web page can read it (X20). Reboot once; if it stays, tell the builder');
      continue;
    }
    if (path === '/presets.json' && r.status === 200 && /HomeGadgets/.test(r.text) && /"(relay|scene|alloff)"/.test(r.text)) {
      add('WARN', id, 'no key found, but presets contain HomeGadgets relay/scene/all-off commands. They cannot work without the key, ' +
        'and the key must never be put there (readme). Use the /home page or Siri links for relays');
      continue;
    }
    if (r.status === 200 && !path.startsWith('/edit')) reachable.push(path);
    add('PASS', id, 'HTTP ' + r.status + (scan ? ', key not in the body' : ' (body not searched)') +
      (OLD_FILES.has(file) && r.status === 404 ? ' (file of an earlier version not present, as expected with RC3b)' : ''));
  }

  // the file list must not show the key files; an open list also means /edit and /upload are open
  const l = await http('GET', '/edit?func=list&path=/');
  if (!l.ok) add(l.skipped ? 'SKIP' : 'WARN', 'sec.edit-list', 'could not check: ' + l.error);
  else if (l.status === 401) {
    add('PASS', 'sec.edit-list', 'HTTP 401: file editor locked by the settings PIN');
    add('PASS', 'sec.edit-open', '/edit and /upload are locked by the settings PIN (it stays unlocked for 15 min after it is entered anywhere)');
  } else if (l.status === 200) {
    const list = tryJson(l.text);
    const names = Array.isArray(list) ? list.map((f) => String(f.name)) : [];
    const secret = names.filter((n) => /wsec/i.test(n));
    if (scan && has(l.text)) add('FAIL', 'sec.edit-list', 'THE KEY IS IN THE FILE LIST');
    else if (secret.length) add('FAIL', 'sec.edit-list', 'the file list shows ' + secret.join(', '));
    else if (!Array.isArray(list)) add('WARN', 'sec.edit-list', 'HTTP 200 but no JSON file list');
    else {
      add('PASS', 'sec.edit-list', names.length + ' files listed, no *wsec* file (config, relay states, old key file) among them');
      add('INFO', 'fs.files', names.join(', '));
    }
    add('WARN', 'sec.edit-open', 'the file editor answered without a settings PIN, so /edit and /upload accept requests from ANY web page ' +
      'opened on your network: files can be deleted, and the configuration /hgcfg_wsec.json replaced, e.g. relays on at power-up ' +
      '(X15; traced in wled00/wled_server.cpp:206-217 and 243-330, not tested). Set a settings PIN: Settings > Security & Updates');
  } else add('WARN', 'sec.edit-list', 'unexpected HTTP ' + l.status);
  return reachable;
}

// ------------------------------------------------------------------ checks: requests the device must refuse

async function checkRefusals(devKey, userKey, reachable) {
  const key = userKey || devKey;
  const r0 = await relayState(0);
  if (r0 === null) {
    add('SKIP', 'sec.api-nokey', 'relay 1 state not readable from /home/live, so the refusal tests are not sent');
  } else {
    // 1) no key, 2) wrong key: both toggles of relay 1 must be refused with 403 and relay 1 must not change
    const wrong = wrongKeyFor(key);
    const probes = [
      ['sec.api-nokey', '/home/api?relay=1&on=t', 'without key'],
      ['sec.api-wrongkey', '/home/api?relay=1&on=t&k=' + enc(wrong), 'with a wrong key'],
    ];
    for (const [id, path, how] of probes) {
      const before = await relayState(0);
      const r = await http('GET', path);
      await sleep(SETTLE_MS);
      const after = await relayState(0);
      if (before !== null && after !== null && before !== after) {
        add('FAIL', id, '!!! RELAY 1 CHANGED FROM ' + onoff(before) + ' TO ' + onoff(after) + ' after a toggle request ' + how +
          ' (' + httpDesc(r) + '). The key protection does not work: switch relay 1 back on /home and do not connect mains. ' +
          '(A wall switch, PIR or timer switching at the same moment would look the same: run the check again.)');
        break; // send no further relay toggles
      }
      if (r.ok && r.status === 403) add('PASS', id, 'HTTP 403 ' + how + ', relay 1 unchanged (' + onoff(after) + ')');
      else add('FAIL', id, 'expected HTTP 403 ' + how + ', got ' + httpDesc(r) + ' (relay 1 unchanged)');
    }
  }

  // 3) the right key with no command: key accepted, nothing to do -> HTTP 400 {"ok":false}
  //    (RC3b home_gadgets.cpp serveApi: key check :2046-2050, no relay/mood/scene/alloff/strip -> ok=false -> 400 at :2085)
  if (key) {
    const r = await http('GET', '/home/api?k=' + enc(key));
    const src = userKey ? '--key' : 'key from /home/cfg';
    if (r.ok && r.status === 400) add('PASS', 'sec.api-key-ok', 'the device accepts the ' + src + ' (HTTP 400 = key OK, no command given, nothing switched)');
    else if (r.ok && r.status === 403) add('FAIL', 'sec.api-key-ok', 'the device refuses the ' + src + ' with HTTP 403: Siri links with this key will not work');
    else add('WARN', 'sec.api-key-ok', 'unexpected ' + httpDesc(r) + ' for a key-only request');
  } else add('SKIP', 'sec.api-key-ok', 'no key known');

  // 4) config upload without key / with a wrong key / with only the PIN: 403, and the config revision must not change
  const uploads = [
    ['sec.cfg-nokey', '/home/cfg', 'without key'],
    ['sec.cfg-wrongkey', '/home/cfg?k=' + enc(wrongKeyFor(key)), 'with a wrong key'],
  ];
  if (OPT.pin) uploads.push(['sec.cfg-pin-only', '/home/cfg?pin=' + enc(OPT.pin), 'with the settings PIN but no key']);
  for (const [id, path, how] of uploads) {
    const rev0 = await liveRev();
    const r = await http('POST', path, { body: '{}', headers: { 'Content-Type': 'application/json' } });
    await sleep(SETTLE_MS);
    const rev1 = await liveRev();
    if (rev0 !== null && rev1 !== null && rev1 !== rev0) {
      add('FAIL', id, 'the configuration upload ' + how + ' was APPLIED (rev ' + rev0 + ' -> ' + rev1 + ', ' + httpDesc(r) + '). ' +
        'The body was {} so nothing changed, but the protection is missing');
    } else if (r.ok && r.status === 403) add('PASS', id, 'HTTP 403 ' + how);
    else add('FAIL', id, 'expected HTTP 403 ' + how + ', got ' + httpDesc(r));
  }

  // what is open by design (information); /home/stats was checked in checkStats()
  const open = [...new Set(['/home', '/home/live', ...(statsSeen ? ['/home/stats'] : []), '/home/cfg', '/json/state', '/json/info', ...reachable])];
  add('INFO', 'open.read', 'answer without key: GET ' + open.join(', ') + '. RC3b serves /home/cfg (with the key), /home/live and /home/stats without a CORS header: ' +
    'other web sites cannot read them, programs on your network can');
  add('INFO', 'open.write', 'open by design (LED only, not sent by this script): POST /json/state {"HomeGadgets":{"mood"|"strip"|"mic"|"lvl"}}. ' +
    'Key needed: every /home/api request, POST /home/cfg, and JSON relay/scene/alloff/away commands');
}

// summary: did every RC3b-specific check pass? (the firmware has no version field for home_gadgets)
function rc3bSummary() {
  const markers = ['fw.page', 'home.unknown', 'sec.pin-set', 'cfg.shape', 'live.fields', 'sec.live-cors', 'stats.shape', 'sec.stats-cors'];
  const bad = markers.filter((id) => {
    const r = results.find((x) => x.check === id);
    return !r || r.status === 'FAIL' || r.status === 'SKIP' || (id === 'fw.page' && r.status !== 'PASS');
  });
  if (bad.length) add('WARN', 'fw.rc3b', 'RC3b not confirmed: ' + bad.join(', ') + ' did not pass or did not run (see those rows)');
  else add('PASS', 'fw.rc3b', 'RC3b feature set present: RC3/RC3b page, 404 for unknown /home/*, pinSet, ' + HG_BUILTIN_MOODS +
    ' built-in moods, /home/live src/ago/px, /home/stats, no CORS header on live and stats. (RC3 and RC3b look the same over the network)');
}

function wrongKeyFor(k) {
  let w = 'zzzzzzzzzz';
  if (k && KEY_RE.test(k)) w = KEY_CHARS[(KEY_CHARS.indexOf(k[0]) + 1) % KEY_CHARS.length] + k.slice(1); // one character off
  if (w === k) w = '2222222222';
  return w;
}

// ------------------------------------------------------------------ switching test (opt-in)

async function restoreRelay(n, i, orig, key) {
  // first through /json/state with the key (tests that path), then through /home/api as a fallback
  await postJson('/json/state', { HomeGadgets: { relay: i, on: orig, k: key } });
  let s = await waitRelay(i, orig, 3000);
  if (s === orig) return 'json';
  await http('GET', '/home/api?relay=' + n + '&on=' + (orig ? 1 : 0) + '&k=' + enc(key));
  s = await waitRelay(i, orig, 3000);
  return s === orig ? 'api' : null;
}

async function switchingTest(n, key, c) {
  const i = n - 1;
  const rc = c && Array.isArray(c.relays) ? c.relays[i] : null;
  if (rc && rc.e) { add('SKIP', 'switch', 'relay ' + n + ' has a pin error (e=' + rc.e + '), fix that first'); return; }
  const orig = await relayState(i);
  if (orig === null) { add('SKIP', 'switch', 'relay ' + n + ' state not readable from /home/live'); return; }
  const target = !orig;
  const name = rc ? '"' + rc.n + '" on GPIO ' + rc.p : '';
  notice('');
  notice('>>> SWITCHING TEST: relay ' + n + ' ' + name + ' is ' + onoff(orig) + ' now.');
  notice('    1. switch it ' + onoff(target) + ' with /home/api and the key, keep it ' + onoff(target) + ' for ' + HOLD_MS / 1000 + ' s');
  notice('    2. send ' + onoff(orig) + ' through /json/state WITHOUT the key (the device must ignore it)');
  notice('    3. switch it back ' + onoff(orig) + ' through /json/state with the key, and check that it is ' + onoff(orig) + ' again');
  notice('    The appliance on this relay WILL switch. Press Ctrl+C within ' + COUNTDOWN_S + ' s to abort.');
  for (let s = COUNTDOWN_S; s > 0; s--) { notice('    ' + s + '...'); await sleep(1000); }

  pendingRestore = { n, i, orig, key };
  const r1 = await http('GET', '/home/api?relay=' + n + '&on=' + (target ? 1 : 0) + '&k=' + enc(key));
  const s1 = await waitRelay(i, target, 3000);
  if (r1.ok && r1.status === 200 && s1 === target) add('PASS', 'switch.api', 'relay ' + n + ' switched ' + onoff(target) + ' via /home/api (HTTP 200) - check that it clicked');
  else add('FAIL', 'switch.api', 'relay ' + n + ' did not switch ' + onoff(target) + ' via /home/api (' + httpDesc(r1) + ', state now ' + (s1 === null ? '?' : onoff(s1)) + ')');

  if (s1 === target) {
    await sleep(HOLD_MS);
    notice('    sending ' + onoff(orig) + ' through /json/state without the key...');
    await postJson('/json/state', { HomeGadgets: { relay: i, on: orig } });
    await sleep(SETTLE_MS);
    const s2 = await relayState(i);
    if (s2 === target) add('PASS', 'sec.json-nokey', 'JSON-state relay command without key was ignored');
    else if (s2 === orig) add('FAIL', 'sec.json-nokey', '!!! JSON-state relay command WITHOUT KEY was accepted (relay ' + n + ' is back ' + onoff(orig) + ')');
    else add('WARN', 'sec.json-nokey', 'relay state not readable after the request');
  }

  const now = await relayState(i);
  if (now !== orig) {
    notice('    restoring relay ' + n + ' to ' + onoff(orig) + '...');
    const how = await restoreRelay(n, i, orig, key);
    if (how === 'json') add('PASS', 'switch.json-key', 'relay ' + n + ' switched back ' + onoff(orig) + ' via /json/state with the key');
    else if (how === 'api') add('WARN', 'switch.json-key', '/json/state with the key did not switch the relay; restored through /home/api instead');
    else add('FAIL', 'switch.json-key', 'the relay did not follow the restore commands');
  }
  const fin = await relayState(i);
  if (fin === orig) {
    add('PASS', 'switch.restore', 'relay ' + n + ' is back in its original state (' + onoff(orig) + '), verified in /home/live');
    pendingRestore = null;
  } else {
    add('FAIL', 'switch.restore', '!!! RELAY ' + n + ' IS ' + (fin === null ? 'IN AN UNKNOWN STATE' : onoff(fin)) + ', IT WAS ' + onoff(orig) +
      ' BEFORE THE TEST. Switch it by hand on the /home page');
  }
}

// ------------------------------------------------------------------ output

const COLORS = { PASS: '\x1b[32m', FAIL: '\x1b[31;1m', WARN: '\x1b[33m', SKIP: '\x1b[90m', INFO: '\x1b[36m' };

function wrap(text, width) {
  const out = []; let line = '';
  for (const word of text.split(/\s+/)) {
    if (!word) continue;
    if (line && line.length + 1 + word.length > width) { out.push(line); line = ''; }
    if (word.length > width) { // very long token (URL)
      if (line) { out.push(line); line = ''; }
      for (let p = 0; p < word.length; p += width) out.push(word.slice(p, p + width));
      continue;
    }
    line = line ? line + ' ' + word : word;
  }
  if (line) out.push(line);
  return out.length ? out : [''];
}

function summary() {
  const s = { PASS: 0, FAIL: 0, WARN: 0, SKIP: 0, INFO: 0 };
  for (const r of results) s[r.status]++;
  return s;
}

function renderTable(startedAt) {
  const color = OPT.color && process.stdout.isTTY && !process.env.NO_COLOR;
  const total = Math.max(80, Math.min(process.stdout.columns || 110, 160));
  const wCheck = Math.max(14, ...results.map((r) => r.check.length));
  const wDetail = Math.max(30, total - 8 - wCheck - 2);
  const lines = [];
  lines.push('hg_check ' + TOOL_VERSION + '  target ' + BASE + '  ' + startedAt.toISOString());
  lines.push('STATUS  ' + 'CHECK'.padEnd(wCheck) + '  DETAIL');
  lines.push('------  ' + '-'.repeat(wCheck) + '  ' + '-'.repeat(Math.min(wDetail, 60)));
  for (const r of results) {
    const d = wrap(r.detail, wDetail);
    const st = color ? COLORS[r.status] + r.status.padEnd(6) + '\x1b[0m' : r.status.padEnd(6);
    lines.push(st + '  ' + r.check.padEnd(wCheck) + '  ' + d[0]);
    for (const more of d.slice(1)) lines.push(' '.repeat(8 + wCheck + 2) + more);
  }
  const s = summary();
  lines.push('');
  lines.push('Summary: ' + s.PASS + ' PASS, ' + s.FAIL + ' FAIL, ' + s.WARN + ' WARN, ' + s.SKIP + ' SKIP, ' + s.INFO + ' INFO' +
    (s.FAIL ? '  ->  fix every FAIL before connecting mains (see BRINGUP.md, "Reading the results")' : ''));
  const pinWarn = results.find((r) => r.check === 'sec.pin-set' && r.status === 'WARN');
  if (pinWarn) lines.push('', (color ? COLORS.WARN : '') + '!!! ' + pinWarn.detail + (color ? '\x1b[0m' : ''));
  return lines.join('\n') + '\n';
}

function finish(startedAt) {
  const s = summary();
  const code = s.FAIL ? 1 : 0;
  let out;
  if (OPT.json) {
    out = JSON.stringify({
      tool: 'hg_check', version: TOOL_VERSION, target: BASE, startedAt: startedAt.toISOString(),
      options: { key: OPT.key ? mask(OPT.key) : null, pin: OPT.pin ? '****' : null, allowSwitching: OPT.allowSwitching, relay: OPT.relay, passive: OPT.passive },
      summary: s, exitCode: code, results,
    }, null, 2) + '\n';
  } else out = renderTable(startedAt);
  process.stdout.write(out, () => process.exit(code));
}

// ------------------------------------------------------------------ main

async function main() {
  try {
    OPT = parseArgs(process.argv.slice(2));
  } catch (e) {
    process.stderr.write('error: ' + e.message + '\n\n' + usage() + '\n');
    process.exit(2);
  }
  if (OPT.help) { process.stdout.write(usage() + '\n'); return; }
  if (typeof fetch !== 'function') { process.stderr.write('error: Node.js 18 or newer is required (no global fetch)\n'); process.exit(2); }
  BASE = baseUrl(OPT.host);
  const startedAt = new Date();

  process.on('SIGINT', async () => {
    if (pendingRestore && !restoring) {
      restoring = true;
      const { n, i, orig, key } = pendingRestore;
      process.stderr.write('\nInterrupted - putting relay ' + n + ' back ' + onoff(orig) + '...\n');
      deviceGone = false; netFailsInRow = 0;
      const how = await restoreRelay(n, i, orig, key);
      process.stderr.write(how ? 'relay ' + n + ' is ' + onoff(orig) + ' again\n'
        : '!!! could not restore relay ' + n + ': switch it by hand on the /home page\n');
    }
    process.exit(130);
  });

  if (!OPT.json) notice('Checking ' + BASE + ' (timeout ' + OPT.timeout + ' ms per request)...');
  if (OPT.relay !== null && !OPT.allowSwitching) add('INFO', 'switch', '--relay given without --allow-switching: no relay is switched');

  const info = await checkInfo();
  if (!info) {
    add('SKIP', 'all other checks', 'device not reachable or not WLED');
    return finish(startedAt);
  }
  await checkHomePage();
  await checkUnknownRoute();
  const cfg = await checkConfig();
  // RC4 and later report their release tag in GET /home/cfg ("rel"); RC3b and older have none
  if (cfg && typeof cfg.rel === 'string' && cfg.rel) add('INFO', 'fw.rel', 'home_gadgets release "' + cfg.rel + '" (from GET /home/cfg)');
  else if (cfg) add('INFO', 'fw.rel', 'no "rel" field in GET /home/cfg: RC3b or older (RC4+ reports it)');
  const devKey = checkKey(cfg, OPT.key);
  await checkLive();
  await checkStats();
  await checkState();
  await checkEffects(cfg);
  await checkPins(cfg);
  const keys = [...new Set([OPT.key, devKey].filter(Boolean))];
  const reachable = await checkLeaks(keys);
  rc3bSummary();
  if (OPT.passive) add('SKIP', 'sec.refusals', '--passive: the requests that the device must refuse were not sent');
  else if (!cfg) add('SKIP', 'sec.refusals', '/home/cfg not available');
  else await checkRefusals(devKey, OPT.key, reachable);
  if (OPT.allowSwitching) {
    if (!cfg) add('SKIP', 'switch', '/home/cfg not available');
    else await switchingTest(OPT.relay, OPT.key, cfg);
  } else add('SKIP', 'switch', 'relay switching test not requested (--allow-switching --relay N --key KEY)');
  if (deviceGone) add('FAIL', 'reach', 'the device stopped answering during the checks (3 failed requests in a row): reboot or crash?');
  finish(startedAt);
}

main().catch((e) => {
  process.stderr.write('internal error: ' + (e && e.stack || e) + '\n');
  process.exit(1);
});
